START TRANSACTION;

CREATE TABLE "MentorCreditGrants" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "LearnerId" integer NOT NULL,
    "UserSubscriptionId" integer NOT NULL,
    "PolicyVersion" integer NOT NULL,
    "InitialQuantity" integer NOT NULL,
    "AvailableQuantity" integer NOT NULL,
    "EffectiveFromUtc" timestamp with time zone NOT NULL,
    "ExpiresAtUtc" timestamp with time zone NOT NULL,
    "CreatedAtUtc" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_MentorCreditGrants" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_MentorCreditGrant_PolicyVersion" CHECK ("PolicyVersion" > 0),
    CONSTRAINT "CK_MentorCreditGrant_Quantity" CHECK ("InitialQuantity" > 0 AND "AvailableQuantity" >= 0 AND "AvailableQuantity" <= "InitialQuantity"),
    CONSTRAINT "FK_MentorCreditGrants_UserSubscriptions_UserSubscriptionId" FOREIGN KEY ("UserSubscriptionId") REFERENCES "UserSubscriptions" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_MentorCreditGrants_Users_LearnerId" FOREIGN KEY ("LearnerId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "MentorCreditEntries" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "CreditGrantId" bigint NOT NULL,
    "LearnerId" integer NOT NULL,
    "EntryType" integer NOT NULL,
    "Amount" integer NOT NULL,
    "OperationKey" character varying(160) NOT NULL,
    "MentorBookingId" integer,
    "Reason" character varying(500),
    "CreatedAtUtc" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_MentorCreditEntries" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_MentorCreditEntry_Amount" CHECK ("Amount" <> 0),
    CONSTRAINT "FK_MentorCreditEntries_MentorBookings_MentorBookingId" FOREIGN KEY ("MentorBookingId") REFERENCES "MentorBookings" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_MentorCreditEntries_MentorCreditGrants_CreditGrantId" FOREIGN KEY ("CreditGrantId") REFERENCES "MentorCreditGrants" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_MentorCreditEntries_Users_LearnerId" FOREIGN KEY ("LearnerId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);

CREATE INDEX "IX_MentorCreditEntries_CreditGrantId_EntryType" ON "MentorCreditEntries" ("CreditGrantId", "EntryType");

CREATE INDEX "IX_MentorCreditEntries_LearnerId" ON "MentorCreditEntries" ("LearnerId");

CREATE INDEX "IX_MentorCreditEntries_MentorBookingId_EntryType" ON "MentorCreditEntries" ("MentorBookingId", "EntryType");

CREATE UNIQUE INDEX "IX_MentorCreditEntries_OperationKey" ON "MentorCreditEntries" ("OperationKey");

CREATE INDEX "IX_MentorCreditGrants_LearnerId_ExpiresAtUtc" ON "MentorCreditGrants" ("LearnerId", "ExpiresAtUtc");

CREATE UNIQUE INDEX "IX_MentorCreditGrants_UserSubscriptionId" ON "MentorCreditGrants" ("UserSubscriptionId");

